    (l, 21, 'phrase', 'Meiner Meinung nach ist das eine gute Idee.', 'في رأيي هذه فكرة جيدة.', null, null, null, null),
    (l, 22, 'phrase', 'Da bin ich anderer Meinung.', 'لدي رأي مختلف في هذا.', null, null, null, null),
